import 'server-only';

import { createHash } from 'crypto';
import type { GeneratedFileSurface } from '@agiworkforce/services';
import { storeMedia, isMediaStorageConfigured } from '@/lib/server/media-storage';
import { insertMediaAsset, type MediaKind } from '@/lib/server/media-assets';
import { logger } from '@/lib/logger';

/**
 * Shared persistence core for the generated-file byte pipeline (managed cloud
 * only). EVERY source of model-generated bytes feeds this one function:
 *
 *   - E2B sandbox files harvested at turn end            (lib/e2b/generated-files.ts)
 *   - E2B runCode rich results (matplotlib chart PNGs)   (tool-loop.ts)
 *   - OpenAI Code Interpreter container files            (lib/server/container-files.ts)
 *   - Anthropic code-execution Files API outputs         (lib/server/container-files.ts)
 *
 * It stores the bytes durably (R2 via storeMedia), catalogs them in
 * `media_assets`, and returns the wire descriptor emitted to clients in the
 * `x_generated_files` SSE delta. The descriptor's `uri` is a SAME-ORIGIN path
 * (`/api/files/{assetId}`) — the only kind of URL the web renderer gates
 * (PDF viewer, inline image, spreadsheet fetch) accept for inline rendering.
 *
 * Contract consumed by web today and mobile/desktop cloud later:
 *   uri: same-origin path on the web app origin; fetch with the user's Clerk
 *        session cookie (browser) or `Authorization: Bearer <jwt>` (native).
 *   checksum_sha256: hash of the exact stored bytes, so any surface can verify
 *        byte round-trip integrity end-to-end.
 */

/** Max bytes per persisted generated file (matches the E2B harvest cap). */
export const MAX_GENERATED_FILE_BYTES = 20 * 1024 * 1024;

/** Wire shape of one generated file in the `x_generated_files` SSE delta. */
export interface GeneratedFileWire {
  id: string;
  file_name: string;
  mime_type: string;
  /** Durable download URL. Same-origin `/api/files/{id}` when cataloged. */
  uri: string;
  byte_count: number;
  /** Coarse kind for client icons: pdf | docx | xlsx | pptx | csv | json | markdown | html | image | archive | other */
  kind: string;
  /** SHA-256 of the stored bytes (hash in == hash out verification). */
  checksum_sha256: string;
  /**
   * UI-ownership classification, derived here at persistence time by
   * `classifyGeneratedFile` (mime + extension, deterministic) — clients
   * never re-derive it. See `GeneratedFileSurface` in the cloud contract
   * for the taxonomy and its relationship to `kind`.
   */
  surface: GeneratedFileSurface;
  /** Client may inline-render the bytes (images/charts, pdf, office/csv). */
  previewable: boolean;
}

// Compile-time drift anchor: the emitted wire shape must stay assignable to
// the shared cloud contract (`packages/services/src/cloud-contracts/
// generated-files.ts`) that mobile/desktop validate stream deltas against.
const _generatedFileWireContractCheck: (
  file: GeneratedFileWire,
) => import('@agiworkforce/services').GeneratedFileWire = (file) => file;
void _generatedFileWireContractCheck;

export type PersistGeneratedFileOutcome =
  | { ok: true; file: GeneratedFileWire }
  | { ok: false; reason: 'not_configured' | 'too_large' | 'storage_error' };

/** Coarse client-icon kind for a filename+mime (shared across all sources). */
export function generatedFileKind(fileName: string, mime: string): string {
  const ext = fileName.toLowerCase().split('.').pop() ?? '';
  if (['pdf', 'docx', 'xlsx', 'pptx', 'csv', 'json', 'html'].includes(ext)) return ext;
  if (ext === 'md' || ext === 'markdown') return 'markdown';
  if (mime.startsWith('image/')) return 'image';
  if (ext === 'zip' || ext === 'tar' || ext === 'gz') return 'archive';
  return 'other';
}

/** Classification of one generated file: which UI surface owns it. */
export interface GeneratedFileClassification {
  surface: GeneratedFileSurface;
  previewable: boolean;
}

/**
 * Source-text formats that render/edit in a panel surface ('artifact'):
 * html, svg, markdown, mermaid, json, and code/plain text.
 */
const ARTIFACT_EXTENSIONS: ReadonlySet<string> = new Set([
  'html',
  'htm',
  'md',
  'markdown',
  'mmd',
  'mermaid',
  'json',
  'txt',
  'tex',
  'xml',
  'yaml',
  'yml',
  'toml',
  // Code text.
  'py',
  'js',
  'jsx',
  'ts',
  'tsx',
  'css',
  'sh',
  'bash',
  'sql',
  'rb',
  'java',
  'c',
  'h',
  'cpp',
  'hpp',
  'cs',
  'go',
  'rs',
  'php',
]);

/**
 * Download deliverables the web app can still inline-render (PDF viewer,
 * docx/spreadsheet/presentation shared renderers in ArtifactPreview).
 */
const PREVIEWABLE_FILE_EXTENSIONS: ReadonlySet<string> = new Set([
  'pdf',
  'docx',
  'xlsx',
  'pptx',
  'csv',
  'tsv',
]);

/**
 * THE classification function for the artifact/file conceptual split
 * (file-creation parity plan Wave A). Deterministic on mime + extension;
 * runs server-side at persistence time only — every wire descriptor and
 * `media_assets` metadata row gets its result, and clients treat it as
 * authoritative instead of re-deriving.
 *
 *   - 'artifact': source text a panel can render/edit (html, svg, markdown,
 *     mermaid, json, code/plain text). Always previewable.
 *   - 'file' + previewable: byte deliverables with an inline renderer —
 *     raster images/charts (how ChatGPT/Claude treat matplotlib PNGs:
 *     downloadable file, inline preview), pdf, docx/xlsx/pptx/csv.
 *   - 'file' + !previewable: archives and unknown binaries (download only).
 */
export function classifyGeneratedFile(fileName: string, mime: string): GeneratedFileClassification {
  const ext = fileName.toLowerCase().split('.').pop() ?? '';
  const mimeLower = mime.toLowerCase();
  // SVG before the generic image/ check: editable source text, not raster.
  if (ext === 'svg' || mimeLower.startsWith('image/svg')) {
    return { surface: 'artifact', previewable: true };
  }
  if (ARTIFACT_EXTENSIONS.has(ext)) return { surface: 'artifact', previewable: true };
  if (PREVIEWABLE_FILE_EXTENSIONS.has(ext)) return { surface: 'file', previewable: true };
  if (mimeLower.startsWith('image/')) return { surface: 'file', previewable: true };
  // Mime fallbacks for extension-less/unknown names. text/csv & tsv are
  // spreadsheet deliverables, checked before the generic text/* artifact rule.
  if (mimeLower === 'text/csv' || mimeLower === 'text/tab-separated-values') {
    return { surface: 'file', previewable: true };
  }
  if (mimeLower === 'application/pdf') return { surface: 'file', previewable: true };
  if (
    mimeLower.startsWith('text/') ||
    mimeLower === 'application/json' ||
    mimeLower === 'application/xml'
  ) {
    return { surface: 'artifact', previewable: true };
  }
  return { surface: 'file', previewable: false };
}

function mediaKindFor(mime: string): MediaKind {
  if (mime.startsWith('image/')) return 'image';
  if (mime.startsWith('video/')) return 'video';
  return 'file';
}

/**
 * Persist one generated file's raw bytes and return its wire descriptor.
 * Never throws: failures return a typed reason so callers can keep today's
 * "skipping" warn AND surface an honest inline note instead of silence.
 */
export async function persistGeneratedFileBytes(params: {
  userId: string;
  data: Buffer;
  mimeType: string;
  filename: string;
  /** Byte source for provenance: 'e2b' | 'openai' | 'anthropic' | ... */
  provider: string;
  /** Provenance detail stored in metadata.origin, e.g. 'e2b-execution'. */
  origin: string;
  model?: string;
  prompt?: string;
  extraMetadata?: Record<string, unknown>;
}): Promise<PersistGeneratedFileOutcome> {
  const { userId, data, mimeType, filename, provider, origin, model, prompt } = params;

  if (!isMediaStorageConfigured()) return { ok: false, reason: 'not_configured' };
  if (data.byteLength > MAX_GENERATED_FILE_BYTES) {
    logger.warn(
      { filename, size: data.byteLength, cap: MAX_GENERATED_FILE_BYTES, provider },
      'Generated file exceeds persistence cap; skipping',
    );
    return { ok: false, reason: 'too_large' };
  }

  try {
    const kind = mediaKindFor(mimeType);
    const classification = classifyGeneratedFile(filename, mimeType);
    const checksum = createHash('sha256').update(data).digest('hex');
    const stored = await storeMedia({ userId, kind, data, contentType: mimeType });
    const assetId = await insertMediaAsset({
      userId,
      kind,
      mimeType,
      byteSize: stored.byteSize,
      storageUrl: stored.url,
      storagePathname: stored.pathname,
      prompt,
      provider,
      model,
      sourceSurface: 'web',
      metadata: {
        filename,
        origin,
        checksumSha256: checksum,
        // Persisted so the library page (Wave D) can filter artifact vs
        // file without re-deriving classification from mime/extension.
        surface: classification.surface,
        previewable: classification.previewable,
        ...(params.extraMetadata ?? {}),
      },
    });

    return {
      ok: true,
      file: {
        id: assetId ?? crypto.randomUUID(),
        file_name: filename,
        mime_type: mimeType,
        // Same-origin serve path when cataloged (renderer gates accept it);
        // the raw R2 public URL is only a download-fallback when the catalog
        // row could not be written (pre-migration deploys).
        uri: assetId ? `/api/files/${assetId}` : stored.url,
        byte_count: stored.byteSize,
        kind: generatedFileKind(filename, mimeType),
        checksum_sha256: checksum,
        surface: classification.surface,
        previewable: classification.previewable,
      },
    };
  } catch (err) {
    logger.warn(
      { err: err instanceof Error ? err.message : String(err), filename, provider, userId },
      'Failed to persist generated file bytes; skipping',
    );
    return { ok: false, reason: 'storage_error' };
  }
}
